sp_widget.css:
.my-accounts-container .panel-heading {
    background-color: #1a3a5c;
    color: #ffffff;
}

.my-accounts-container .panel-title {
    font-size: 18px;
    font-weight: 600;
}

.my-accounts-container .table thead th {
    background-color: #f5f5f5;
    font-weight: 600;
    border-bottom: 2px solid #ddd;
}

.my-accounts-container .table tbody td {
    vertical-align: middle;
}

.my-accounts-container .empty-state {
    padding: 48px 16px;
}

sp_widget.script:
(function() {
    data.accounts = [];

    var userId = gs.getUserID();
    var gr = new GlideRecord('x_274351_finance_0_accounts');
    gr.addQuery('holder', userId);
    gr.orderBy('number');
    gr.setLimit(50);
    gr.query();
    while (gr.next()) {
        var isActive = gr.getValue('active') === '1' || gr.getValue('active') === 'true';
        data.accounts.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            account_type: gr.getDisplayValue('account_type'),
            balance: parseFloat(gr.getValue('balance') || 0).toFixed(2),
            status: isActive ? 'Active' : 'Inactive',
            statusClass: isActive ? 'label-success' : 'label-default'
        });
    }
})();
